    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != c.owner());
        vm.prank(c.owner());
        try c.setOwner(newOwner) {
            assertTrue(c.owner() == newOwner, "owner must equal the requested newOwner");
        } catch {
            assertTrue(true);
        }
    }
